CREATE TABLE `business` (
  `businessId` int NOT NULL AUTO_INCREMENT COMMENT '商家编号',
  `businessName` varchar(40) NOT NULL COMMENT '商家名称',
  `businessAddress` varchar(50) DEFAULT NULL COMMENT '商家地址',
